function pbmit_card_static_box(){const container=document.querySelector('.pbmit-element-static-box-style-5');if(!container)return;ScrollTrigger.matchMedia({"(min-width: 1025px)":()=>{const panels=gsap.utils.toArray(".pbmit-box-wrapper");const headingSticky=document.querySelector('.pbmit-heading-box-sticky');const btnSticky=document.querySelector('.pbmit-btn-box-sticky');if(!panels.length)return;const panelHeight=panels[0].offsetHeight+80;const topSpacing=80;panels.forEach((panel,i)=>{gsap.set(panel,{top:i*50});gsap.to(panel,{scrollTrigger:{trigger:panel,start:`top bottom-=100`,end:`top+=${80 + panels.length * 2}`,scrub:!0,},ease:"none",scale:1-(panels.length-i)*0.025,});ScrollTrigger.create({trigger:panel,start:"top 80px",endTrigger:container,end:`bottom top+=${panelHeight + panels.length}`,pin:!0,pinSpacing:!1,})});if(headingSticky||btnSticky){gsap.to(headingSticky,{scrollTrigger:{trigger:container,start:`top top+=${topSpacing}`,end:`bottom top+=${panelHeight + panels.length}`,scrub:!0,pin:headingSticky,pinSpacing:!1,}});gsap.to(btnSticky,{scrollTrigger:{trigger:container,start:`top top+=${topSpacing}`,end:`bottom top+=${panelHeight + panels.length}`,scrub:!0,pin:btnSticky,pinSpacing:!1,}})}},"(max-width:1024px)":()=>{ScrollTrigger.getAll().forEach(st=>st.kill(!0))}})}
function pbmit_miconheading_scroll(){var $container=jQuery('.pbmit-scrolling .pbmit-element-miconheading-style-26 .pbmit-element-inner');if(!$container.length)return;var topSpacing=200;ScrollTrigger.matchMedia({"(min-width: 1025px)":function(){var $header=$container.find('.pbmit-ele-header-area');var $posts=$container.find('.pbmit-element-posts-wrapper');var headerHeight=$header.outerHeight();var postsHeight=$posts[0].scrollHeight;var viewportHeight=window.innerHeight;gsap.set($posts[0],{y:500});ScrollTrigger.create({trigger:$container[0],start:"top top",end:()=>`+=${postsHeight - viewportHeight + headerHeight + topSpacing}`,pin:!0,pinSpacing:!1,scrub:1.2});gsap.fromTo($posts[0],{y:500},{y:()=>-(postsHeight-viewportHeight+headerHeight+topSpacing),ease:"none",scrollTrigger:{trigger:$container[0],start:"top top",pinSpacing:!1,end:()=>`+=${postsHeight - viewportHeight + headerHeight + topSpacing}`,scrub:1.2}})},"(max-width: 1024px)":function(){ScrollTrigger.getAll().forEach(st=>st.kill(!0));topSpacing=0;var $posts=$container.find('.pbmit-element-posts-wrapper');var $header=$container.find('.pbmit-ele-header-area');gsap.set($posts[0],{y:0,transition:'none'});gsap.set($header[0],{position:'relative',top:'auto'})}})}
function pbmit_testimonial_animation(){ScrollTrigger.matchMedia({"(min-width: 768px)":()=>{var triggerEl=document.querySelector('.pbmit-testimonial-sticky');var pinEl=triggerEl;var startPos="top top";if(!triggerEl){triggerEl=document.querySelector('.pbmit-element-testimonial-style-11 .pbmit-ele-header-area');pinEl=document.querySelector('.pbmit-element-testimonial-style-11');startPos="top 50px"}
if(!triggerEl||!pinEl)return;var areas=gsap.utils.toArray(".pbmit-testimonial-style-11");var itemsToAnimate=areas.slice(1).reverse();itemsToAnimate.forEach(function(item,index){gsap.set(item,{rotate:-(index*2)-2,yPercent:0,willChange:"transform"})});var pbmit=gsap.timeline({scrollTrigger:{trigger:triggerEl,pin:pinEl,start:startPos,end:"+="+(itemsToAnimate.length*300),scrub:1.5,pinSpacing:!0}});itemsToAnimate.forEach(function(item,index){pbmit.to(item,{yPercent:-200,rotate:0,ease:"power1.out"},index*0.3)})}})}
function pbmit_slider_animation(){const textContent=' .n2-ss-item-content';const animationStyles={'up-1':{opacity:0,y:'90%',rotateX:-40,ease:'back.out(1.7)'},'up-2':{opacity:0,y:'80%',rotation:15,ease:'power3.out'},'up-3':{opacity:0,y:'70%',scale:0.8,ease:'power2.out'},'down-1':{opacity:0,y:'-90%',rotateX:40,ease:'power4.inOut'},'down-2':{opacity:0,y:'-80%',rotation:-15,ease:'power3.out'},'down-3':{opacity:0,x:'-50%',rotation:-10,ease:'power2.out'},'flip-1':{opacity:0,rotationX:90,ease:'power4.inOut'}};const RESET={opacity:1,x:0,y:0,scale:1,rotation:0,rotateX:0,rotateY:0,filter:'blur(0px)'};const allSelectors=Object.keys(animationStyles).map(k=>`.pbmit-text-ani-${k}${textContent}`).join(',');document.querySelectorAll(allSelectors).forEach(text=>{if(text._split)return;text._split=new SplitText(text,{type:'words,chars',wordsClass:'word',charsClass:'char'});gsap.set(text._split.chars,{opacity:0})});function getDelay(text){const raw=getComputedStyle(text.closest('[class*="pbmit-text-ani-"]')).getPropertyValue('--animation-delay').trim();return parseFloat(raw)||0}
function animateText(activeSlide,styleClass,settings){const{ease,...fromProps}=settings;const toProps=Object.keys(fromProps).reduce((acc,key)=>{if(key in RESET)acc[key]=RESET[key];return acc},{});activeSlide.querySelectorAll(`.pbmit-text-ani-${styleClass}${textContent}`).forEach(text=>{const chars=text._split?.chars;if(!chars?.length)return;const is3D=['flip-1','down-1'].includes(styleClass);gsap.set(chars,{...fromProps,...(is3D?{transformPerspective:400,}:{})});gsap.to(chars,{...toProps,...(is3D?{rotationX:0}:{}),duration:1,delay:getDelay(text),stagger:is3D?0.1:0.02,ease})})}
let lastActiveSlide=null;function animateActiveSlide(){const activeSlide=document.querySelector('.n2-ss-slide-active');if(!activeSlide||activeSlide===lastActiveSlide)return;lastActiveSlide=activeSlide;Object.entries(animationStyles).forEach(([styleClass,settings])=>{animateText(activeSlide,styleClass,settings)})}
animateActiveSlide();const slides=document.querySelectorAll('.n2-ss-slide');if(!slides.length)return;const observer=new MutationObserver(animateActiveSlide);slides.forEach(slide=>observer.observe(slide,{attributes:!0,attributeFilter:['class']}));return()=>observer.disconnect()}
